{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "Coptisine, the closest quaternary protoberberine analogue with two methylenedioxy groups, was detected in mouse brain homogenates by LC-MS/MS, directly demonstrating BBB passage.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Berberine, a closely related quaternary protoberberine, was detected in rat CSF at 41.07 ng/mL after systemic administration, confirming CNS access despite its permanent charge.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Berberrubine, another quaternary protoberberine analogue, reached 37.44 ng/mL in rat CSF, supporting CNS access for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Corynoline, a methylenedioxy-containing alkaloid with the same fused-ring system, crossed the BBB and achieved relatively high brain concentrations in mice.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "A review statement that berberine cannot easily pass the BBB is outweighed by direct brain and CSF detection in multiple pharmacokinetic studies.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a quaternary methylenedioxy-substituted protoberberine-like alkaloid. The closest analogue coptisine is directly detected in brain, and related quaternary protoberberines (berberine, berberrubine) are found in CSF after systemic dosing. Although some qualitative statements question berberine's BBB passage, direct pharmacokinetic and CSF measurements outweigh them. Prediction: pass.",
  "evidence_gaps": [
    "No direct brain or CSF measurement for the exact query molecule; prediction relies on close analogues.",
    "Quantitative unbound brain-to-plasma ratio and potential efflux-transporter contribution are not directly assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

